import{_ as e,o as a,c as o,ah as n}from"./chunks/framework.BsNNkeaH.js";const u=JSON.parse('{"title":"Accounting export","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/caissier/export-comptable.md","filePath":"src/en/guide/caissier/export-comptable.md"}'),r={name:"en/guide/caissier/export-comptable.md"};function s(i,t,c,d,l,p){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="accounting-export" tabindex="-1">Accounting export <a class="header-anchor" href="#accounting-export" aria-label="Permalink to &quot;Accounting export&quot;">​</a></h1><p>From the <strong>Billing</strong> page, three buttons let you download the school&#39;s financial data in a form your accountant can use, or for your own records. Each button downloads the file immediately, with no setup required.</p><table tabindex="0"><thead><tr><th>Button</th><th>File contents</th><th>Typical use</th></tr></thead><tbody><tr><td><strong>Export as CSV</strong></td><td>A raw table of every payment collected: student, fee item, amount, method, reference, date, and who recorded it.</td><td>Checking or sorting payments in a spreadsheet.</td></tr><tr><td><strong>Export SYSCOHADA</strong></td><td>A combined cash journal: payments received and approved expenses, sorted by date with a debit/credit account for each movement.</td><td>Feeding the school&#39;s accounting under the SYSCOHADA chart of accounts.</td></tr><tr><td><strong>Export by class</strong></td><td>A detailed statement, class by class then student by student: each fee item with the amount due, amount paid, remaining balance, and percent paid.</td><td>Reviewing a class&#39;s payment status with a teacher or site director.</td></tr></tbody></table><h2 id="export-as-csv" tabindex="-1">Export as CSV <a class="header-anchor" href="#export-as-csv" aria-label="Permalink to &quot;Export as CSV&quot;">​</a></h2><p>Click <strong>Export as CSV</strong> to download a file listing every recorded payment individually. This file is useful for quickly finding a specific payment or importing it into another tool.</p><h2 id="export-in-syscohada-format" tabindex="-1">Export in SYSCOHADA format <a class="header-anchor" href="#export-in-syscohada-format" aria-label="Permalink to &quot;Export in SYSCOHADA format&quot;">​</a></h2><p>Click <strong>Export SYSCOHADA</strong> to download a cash journal that reconciles payments received (cash inflows) with expenses that have already been <strong>approved</strong> (cash outflows) — see <a href="/en/guide/caissier/depenses.html">Expenses</a>. Each row shows the date, the journal concerned, the debit and credit accounts, a label, and an amount, in a format an accounting firm working with the SYSCOHADA chart of accounts can use directly.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Only expenses already approved by an administrator appear in this export; an expense still pending does not show up here.</p></div><h2 id="export-by-class" tabindex="-1">Export by class <a class="header-anchor" href="#export-by-class" aria-label="Permalink to &quot;Export by class&quot;">​</a></h2><p>Click <strong>Export by class</strong> to download a statement that details, for every student in every class, the status of each fee item (amount due, amount paid, remaining balance, percent paid) along with their list of payments. This is the best format for a class-by-class follow-up.</p>',10)])])}const m=e(r,[["render",s]]);export{u as __pageData,m as default};
